pub(super) const FEELING_PHRASES: &[(&str, &str)] = &[
    (
        r#"(?<![a-z0-9])(?:(?:my|me)\s+heart(?:'s|s)?\s+(?:(?:is|was|feels|felt|looks)\s+)?(?:(?:so|really|very|too|pretty|quite|still|just|totally|completely|absolutely|utterly|properly|well|a|bit|a|little|kind|of|sort|of|that|this)\s+)*(?:broken|breaking|shattered|crushed|torn|broke|snapped|in\ pieces|in\ bits|in\ two)\b(?!\s+open)(?:\s+(?:in\s+(?:two|bits|pieces)|into\s+(?:a\s+million\s+)?pieces|to\s+pieces))?|(?:[a-z']+\s+)?(?:broke|breaks|breaking|broken)\s+(?:my|me)\s+heart)"#,
        " i am heartbroken ",
    ),
    (
        r#"(?<![a-z0-9])(?:(?:my|me)\s+heart(?:'s|s)?\s+(?:(?:is|was|feels|felt|looks)\s+)?(?:(?:so|really|very|too|pretty|quite|still|just|totally|completely|absolutely|utterly|properly|well|a|bit|a|little|kind|of|sort|of|that|this)\s+)*(?:sank|sinking|dropped)\b(?!\s+open)(?:\s+(?:in\s+(?:two|bits|pieces)|into\s+(?:a\s+million\s+)?pieces|to\s+pieces))?|(?:[a-z']+\s+)?(?:broke|breaks|breaking|broken)\s+(?:my|me)\s+heart)"#,
        " i am disappointed ",
    ),
    (
        r#"(?<![a-z0-9])broken[\s-]?hearted(?![a-z0-9])"#,
        " heartbroken ",
    ),
    (
        r#"(?<![a-z0-9])broken[\s-]?heart(?![a-z0-9])"#,
        " heartbroken ",
    ),
    (
        r#"(?<![a-z0-9])heart[\s-]?broken(?![a-z0-9])"#,
        " heartbroken ",
    ),
    (
        r#"(?<![a-z0-9])(?:my|me)\s+(?:whole\s+)?(?:world|life)\s+(?:fell|has\s+fallen|had\s+fallen|is\s+falling|came|came\s+crashing)\s+(?:apart|down|crashing\s+down)(?![a-z0-9])"#,
        " i am sad ",
    ),
    (
        r#"(?<![a-z0-9])(?:(?:my|me)\s+)?heart(?:'s|s)?\s+(?:(?:is|was|feels|felt)\s+)?in\s+(?:my|me)\s+(?:mouth|boots|throat|stomach|shoes)(?![a-z0-9])"#,
        " i am nervous ",
    ),
    (
        r#"(?<![a-z0-9])(?:im|i\s+am|i\s+feel|i\s+felt|i\s+was)\s+(?:so\s+|really\s+|totally\s+|completely\s+|utterly\s+|absolutely\s+)?crushed(?![a-z0-9])(?!\s+by\b)"#,
        " i am sad ",
    ),
];

